package com.wangc.bill.reference;

import android.content.Context;
import android.os.Parcel;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.json.JSONObject;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public final class OriginalCurdHistoryDeviceTest {
    private static final String DATABASE="reference_original_curd_test.sqlite";
    private Context context;private ReferenceStore store;private OriginalCurdHistoryRepository repository;
    @Before public void open(){context=ApplicationProvider.getApplicationContext();context.deleteDatabase(DATABASE);store=new ReferenceStore(context,DATABASE);store.getWritableDatabase();repository=new OriginalCurdHistoryRepository(store);}
    @After public void close(){if(store!=null)store.close();context.deleteDatabase(DATABASE);}
    private OriginalCurdHistoryRepository.Data data(int type,int id,int action){OriginalCurdHistoryRepository.Data d=new OriginalCurdHistoryRepository.Data();d.type=type;d.typeId=id;d.actionType=action;d.billBookSemanticId=Long.MAX_VALUE;d.billOwnerSemanticId=-7;return d;}
    @Test public void exactIdentityDedupeIsScopedByOwnerAndAction(){OriginalCurdHistoryRepository.Data d=data(6,99,1);OriginalCurdHistoryRepository.SaveResult a=repository.add(7,d);assertTrue(a.saved);assertFalse(a.alreadyPresent);assertEquals(a.rowId,repository.add(7,d).rowId);assertTrue(repository.add(7,d).alreadyPresent);repository.add(8,d);repository.add(7,data(6,99,2));assertEquals(2,repository.forOwner(7).size());assertEquals(1,repository.forOwner(8).size());assertEquals(0,d.ownerSemanticId);assertEquals(Long.MAX_VALUE,repository.forOwner(7).get(0).optLong("bill_book_semantic_id"));}
    @Test public void zeroActionRemovesOnlyOtherActionsForThatSameOwnerAndEntity(){repository.add(7,data(6,99,1));repository.add(7,data(6,99,2));repository.add(7,data(6,100,1));repository.add(8,data(6,99,1));repository.add(7,data(6,99,0));assertEquals(2,repository.forOwner(7).size());assertEquals(1,repository.forOwner(8).size());assertEquals(0,repository.deleteAction(7,6,99,1));assertEquals(1,repository.deleteEntity(7,6,99));assertEquals(1,repository.forOwner(7).size());assertEquals(0,store.scalar("SELECT COUNT(*) n FROM asset_histories"));}
    @Test public void assetOperationPreservesTheOuterDefaultOwnerAndIntNarrowingQuirk(){long semantic=(long)Integer.MAX_VALUE+2;repository.recordAssetOperation(0,semantic);assertEquals(Integer.MIN_VALUE+1,repository.forOwner(0).get(0).optInt("entity_semantic_id"));OriginalCurdHistoryRepository.SaveResult blocked=repository.recordAssetOperation(7,semantic);assertTrue(blocked.alreadyPresent);assertTrue(repository.forOwner(7).isEmpty());assertEquals(0,repository.deleteEntity(0,6,semantic));assertEquals(1,repository.deleteEntity(0,6,(int)semantic));repository.recordAssetOperation(7,semantic);assertEquals(1,repository.forOwner(7).size());}
    @Test public void failedIndependentSaveDoesNotUndoTheEarlierActionCleanup(){repository.add(7,data(6,99,1));store.getWritableDatabase().execSQL("CREATE TEMP TRIGGER fail_curd BEFORE INSERT ON original_curd_histories BEGIN SELECT RAISE(ABORT,'synthetic rejection'); END");OriginalCurdHistoryRepository.SaveResult failed=repository.add(7,data(6,99,0));assertFalse(failed.saved);assertFalse(failed.failureType.isEmpty());assertTrue(repository.forOwner(7).isEmpty());assertEquals(0,store.scalar("SELECT COUNT(*) n FROM accounts"));assertEquals(0,store.scalar("SELECT COUNT(*) n FROM asset_histories"));}
    @Test public void curdRowsRoundTripWithoutReplayingAnAssetOrBalance(){repository.add(-7,data(-3,Integer.MIN_VALUE,-9));JSONObject backup=store.backup();repository.clearOwner(-7);store.restore(backup);JSONObject row=repository.forOwner(-7).get(0);assertEquals(Integer.MIN_VALUE,row.optInt("entity_semantic_id"));assertEquals(-9,row.optInt("action_type"));assertEquals(Long.MAX_VALUE,row.optLong("bill_book_semantic_id"));assertEquals(0,store.scalar("SELECT COUNT(*) n FROM accounts"));assertEquals(0,store.scalar("SELECT COUNT(*) n FROM transactions"));assertEquals(0,store.scalar("SELECT COUNT(*) n FROM asset_histories"));repository.validateRestored();}
    @Test public void realParcelKeepsTheOriginalFieldOrderAndOmittedRemainder(){OriginalCreditBill b=new OriginalCreditBill();b.setInDate("range");b.setTime(12);b.setTitle("title");b.setNumber(1.25);b.setInstalmentNumber(2.5);b.setYear(2025);b.setMonth(1);b.setMaxTime(30);b.setMinTime(10);b.setCurrent(true);b.setAssetId(Long.MAX_VALUE);b.setRepaymentDay("2025-01-31");b.setRemindNumber(3.75);b.setServiceCost(.25);b.setRemainServiceCost(.125);OriginalCreditBillInfo i=new OriginalCreditBillInfo();i.setTitle("detail");i.setRemark("remark");i.setNumber(-1.25);i.setIcon("font:分");i.setBillId(99);i.setDate(15);b.addBill(i);Parcel p=Parcel.obtain();try{b.writeToParcel(p,0);p.setDataPosition(0);assertEquals("range",p.readString());assertEquals(12,p.readLong());assertEquals("title",p.readString());p.setDataPosition(0);OriginalCreditBill read=OriginalCreditBill.CREATOR.createFromParcel(p);assertEquals(Long.MAX_VALUE,read.getAssetId());assertEquals(.25,read.getServiceCost(),0);assertEquals(0,read.getRemainServiceCost(),0);assertNull(read.getInstalmentInfoList());assertEquals(-1.25,read.getBillInfoList().get(0).getNumber(),0);assertEquals(99,read.getBillInfoList().get(0).getBillId());assertEquals(15,read.getBillInfoList().get(0).getDate());assertEquals("remark",read.getBillInfoList().get(0).getRemark());}finally{p.recycle();}}
}
